using System;using System.IO;using System.Runtime.InteropServices;
namespace BeamScheduleFormatter {
sealed class ExcelLiveLink:IDisposable {
 dynamic app,book;bool isolated;public string PathName{get;private set;}
 public ExcelLiveLink(string path,bool visible=true){PathName=Path.GetFullPath(path);isolated=!visible;try{var type=Type.GetTypeFromProgID("Excel.Application");if(type==null)throw new Exception("Install desktop Microsoft Excel to use the live workbook link.");if(!File.Exists(PathName)){using(var input=typeof(ExcelLiveLink).Assembly.GetManifestResourceStream("BeamSummaryTemplate.xlsx"))using(var output=File.Create(PathName)){if(input==null)throw new Exception("Excel template resource missing.");input.CopyTo(output);}}if(visible){try{app=Marshal.GetActiveObject("Excel.Application");}catch(COMException){}}if(app==null)app=Activator.CreateInstance(type);foreach(dynamic candidate in app.Workbooks){if(string.Equals((string)candidate.FullName,PathName,StringComparison.OrdinalIgnoreCase)){book=candidate;break;}}if(book==null)book=app.Workbooks.Open(PathName,0,false);if((bool)book.ReadOnly)throw new Exception("The linked Excel workbook is read-only.");if(Convert.ToString(book.Worksheets["RawData"].Range["N1"].Value2)!="BeamToolsSummaryV1")throw new Exception("Choose a Beam Summary workbook created by this app.");if(visible)app.Visible=true;}catch{Dispose();throw;}}
 public void Update(object[,] rows,string status){dynamic raw=book.Worksheets["RawData"],table=raw.ListObjects["BeamData"];int old=(int)table.Range.Rows.Count;raw.Range["A2:L"+Math.Max(2,old)].ClearContents();int count=rows.GetLength(0);table.Resize(raw.Range["A1:L"+(Math.Max(1,count)+1)]);if(count>0)raw.Range["A2:L"+(count+1)].Value2=rows;else raw.Range["D2:L2"].Value2=0;raw.Range["F2:K"+(Math.Max(1,count)+1)].NumberFormat="0.00";book.Worksheets["Summary"].Range["B3"].Value2=status;book.Worksheets["Summary"].Range["B4"].Value2="Updated: "+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");app.CalculateFull();book.Save();}
 public double Value(string cell){return Convert.ToDouble(book.Worksheets["Summary"].Range[cell].Value2);}
 public void Dispose(){try{if(isolated&&book!=null)book.Close(false);}catch{}try{if(isolated&&app!=null)app.Quit();}catch{}if(book!=null&&Marshal.IsComObject(book))Marshal.ReleaseComObject(book);if(app!=null&&Marshal.IsComObject(app))Marshal.ReleaseComObject(app);book=null;app=null;}
}
}
